namespace sv_5a84934b1b1b46e183568e34de24146d.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    DateTimeOffset Timestamp);

using sv_5a84934b1b1b46e183568e34de24146d.Client.Models;

namespace sv_5a84934b1b1b46e183568e34de24146d.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_5a84934b1b1b46e183568e34de24146d.Client.Models;
using sv_5a84934b1b1b46e183568e34de24146d.Client.Services;

namespace sv_5a84934b1b1b46e183568e34de24146d.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 18, 14, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 12, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", new DateTimeOffset(2026, 7, 13, 3, 30, 0, TimeSpan.Zero)),
                new("In transit to destination", new DateTimeOffset(2026, 7, 14, 11, 15, 0, TimeSpan.Zero)),
            }),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 7, 10, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", new DateTimeOffset(2026, 7, 10, 7, 45, 0, TimeSpan.Zero)),
                new("Delivered", new DateTimeOffset(2026, 7, 10, 11, 22, 0, TimeSpan.Zero)),
            }),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 7, 22, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", new DateTimeOffset(2026, 7, 14, 16, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@using sv_5a84934b1b1b46e183568e34de24146d.Client.Models
@using sv_5a84934b1b1b46e183568e34de24146d.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _lastLoadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload if the tracking number actually changed
        if (string.Equals(_lastLoadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase)
            && !_loading)
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        CancelPendingRequest();

        _lastLoadedTrackingNumber = TrackingNumber;
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was intentionally cancelled — nothing to show
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            // Only update loading state if this CTS is still the active one
            if (_cts == cts)
            {
                _loading = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPendingRequest()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingRequest();
    }
}

